import{_ as n,V as s,W as a,Z as t}from"./framework-828e3e61.js";const e={},p=t(`<h1 id="jackson-unknown-properties" tabindex="-1"><a class="header-anchor" href="#jackson-unknown-properties" aria-hidden="true">#</a> jackson unknown properties</h1><h2 id="_1-概述" tabindex="-1"><a class="header-anchor" href="#_1-概述" aria-hidden="true">#</a> <strong>1. 概述</strong></h2><p>在本教程中，我们将了解 Jackson 2.x 的解组过程，特别<strong>是如何处理具有未知属性的 JSON 内容</strong>。</p><h2 id="_2-解组带有附加-未知字段的-json" tabindex="-1"><a class="header-anchor" href="#_2-解组带有附加-未知字段的-json" aria-hidden="true">#</a> <strong>2. 解组带有附加/未知字段的 JSON</strong></h2><p>JSON 输入有各种形状和大小，大多数时候，我们需要将其映射到具有一定数量字段的预定义 Java 对象。</p><p>目标是简单地<strong>忽略任何无法映射到现有 Java 字段的 JSON 属性</strong>。</p><p>例如，假设我们需要将 JSON 解组为以下 Java 实体：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDto</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token class-name">String</span> stringValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> intValue<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">boolean</span> booleanValue<span class="token punctuation">;</span>

    <span class="token comment">// standard constructor, getters and setters </span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-1-未知字段上的unrecognizedpropertyexception" tabindex="-1"><a class="header-anchor" href="#_2-1-未知字段上的unrecognizedpropertyexception" aria-hidden="true">#</a> <strong>2.1.未知字段上的UnrecognizedPropertyException</strong></h3><p>尝试将具有未知属性的 JSON 解组到这个简单的 Java 实体将导致<em>com.fasterxml.jackson.databind.exc.UnrecognizedPropertyException</em>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span><span class="token punctuation">(</span>expected <span class="token operator">=</span> <span class="token class-name">UnrecognizedPropertyException</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenJsonHasUnknownValues_whenDeserializing_thenException</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">JsonMappingException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> jsonAsString <span class="token operator">=</span> 
        <span class="token string">&quot;{&quot;</span>stringValue<span class="token string">&quot;:&quot;</span>a<span class="token string">&quot;,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>intValue<span class="token string">&quot;:1,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>booleanValue<span class="token string">&quot;:true,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>stringValue2<span class="token string">&quot;:&quot;</span>something<span class="token string">&quot;}&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">MyDto</span> readValue <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">readValue</span><span class="token punctuation">(</span>jsonAsString<span class="token punctuation">,</span> <span class="token class-name">MyDto</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertNotNull</span><span class="token punctuation">(</span>readValue<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这将失败，但出现以下异常：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>com.fasterxml.jackson.databind.exc.UnrecognizedPropertyException: 
Unrecognized field <span class="token string">&quot;stringValue2&quot;</span> <span class="token punctuation">(</span>class org.baeldung.jackson.ignore.MyDto<span class="token punctuation">)</span>, 
not marked as ignorable <span class="token punctuation">(</span><span class="token number">3</span> known properties: <span class="token string">&quot;stringValue&quot;</span>, <span class="token string">&quot;booleanValue&quot;</span>, <span class="token string">&quot;intValue&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-使用objectmapper处理未知字段" tabindex="-1"><a class="header-anchor" href="#_2-2-使用objectmapper处理未知字段" aria-hidden="true">#</a> <strong>2.2.使用ObjectMapper处理未知字段</strong></h3><p><strong>我们现在可以配置完整的ObjectMapper以忽略 JSON 中的未知属性：</strong></p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">configure</span><span class="token punctuation">(</span><span class="token class-name">DeserializationFeature</span><span class="token punctuation">.</span><span class="token constant">FAIL_ON_UNKNOWN_PROPERTIES</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后我们应该能够将这种 JSON 读入预定义的 Java 实体中：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenJsonHasUnknownValuesButJacksonIsIgnoringUnknowns_whenDeserializing_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">JsonMappingException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">String</span> jsonAsString <span class="token operator">=</span> 
        <span class="token string">&quot;{&quot;</span>stringValue<span class="token string">&quot;:&quot;</span>a<span class="token string">&quot;,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>intValue<span class="token string">&quot;:1,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>booleanValue<span class="token string">&quot;:true,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>stringValue2<span class="token string">&quot;:&quot;</span>something<span class="token string">&quot;}&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
      <span class="token punctuation">.</span><span class="token function">configure</span><span class="token punctuation">(</span><span class="token class-name">DeserializationFeature</span><span class="token punctuation">.</span><span class="token constant">FAIL_ON_UNKNOWN_PROPERTIES</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">MyDto</span> readValue <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">readValue</span><span class="token punctuation">(</span>jsonAsString<span class="token punctuation">,</span> <span class="token class-name">MyDto</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertNotNull</span><span class="token punctuation">(</span>readValue<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">getStringValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">isBooleanValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">getIntValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-在类级别处理未知字段" tabindex="-1"><a class="header-anchor" href="#_2-3-在类级别处理未知字段" aria-hidden="true">#</a> <strong>2.3.在类级别处理未知字段</strong></h3><p><strong>我们还可以将单个类标记为接受未知字段</strong>，而不是整个 Jackson <em>ObjectMapper</em>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@JsonIgnoreProperties</span><span class="token punctuation">(</span>ignoreUnknown <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MyDtoIgnoreUnknown</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>现在我们应该能够测试与以前相同的行为。未知字段将被简单地忽略，并且仅映射已知字段：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenJsonHasUnknownValuesButIgnoredOnClass_whenDeserializing_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span> 
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">JsonMappingException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
 
    <span class="token class-name">String</span> jsonAsString <span class="token operator">=</span>
        <span class="token string">&quot;{&quot;</span>stringValue<span class="token string">&quot;:&quot;</span>a<span class="token string">&quot;,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>intValue<span class="token string">&quot;:1,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>booleanValue<span class="token string">&quot;:true,&quot;</span> <span class="token operator">+</span>
        <span class="token string">&quot;&quot;</span>stringValue2<span class="token string">&quot;:&quot;</span>something<span class="token string">&quot;}&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">MyDtoIgnoreUnknown</span> readValue <span class="token operator">=</span> mapper
      <span class="token punctuation">.</span><span class="token function">readValue</span><span class="token punctuation">(</span>jsonAsString<span class="token punctuation">,</span> <span class="token class-name">MyDtoIgnoreUnknown</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertNotNull</span><span class="token punctuation">(</span>readValue<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">getStringValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">isBooleanValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">getIntValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-解组不完整的-json" tabindex="-1"><a class="header-anchor" href="#_3-解组不完整的-json" aria-hidden="true">#</a> <strong>3. 解组不完整的 JSON</strong></h2><p>与其他未知字段类似，解组不完整的 JSON（不包含 Java 类中所有字段的 JSON）对于 Jackson 来说不是问题：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">givenNotAllFieldsHaveValuesInJson_whenDeserializingAJsonToAClass_thenCorrect</span><span class="token punctuation">(</span><span class="token punctuation">)</span> 
  <span class="token keyword">throws</span> <span class="token class-name">JsonParseException</span><span class="token punctuation">,</span> <span class="token class-name">JsonMappingException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> jsonAsString <span class="token operator">=</span> <span class="token string">&quot;{&quot;</span>stringValue<span class="token string">&quot;:&quot;</span>a<span class="token string">&quot;,&quot;</span>booleanValue<span class="token string">&quot;:true}&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">ObjectMapper</span> mapper <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ObjectMapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name">MyDto</span> readValue <span class="token operator">=</span> mapper<span class="token punctuation">.</span><span class="token function">readValue</span><span class="token punctuation">(</span>jsonAsString<span class="token punctuation">,</span> <span class="token class-name">MyDto</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">assertNotNull</span><span class="token punctuation">(</span>readValue<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">getStringValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">assertThat</span><span class="token punctuation">(</span>readValue<span class="token punctuation">.</span><span class="token function">isBooleanValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">equalTo</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-结论" tabindex="-1"><a class="header-anchor" href="#_4-结论" aria-hidden="true">#</a> <strong>4.结论</strong></h2><p>在本文中，我们讨论了使用 Jackson 反序列化具有附加未知属性的 JSON。</p><p>这是使用 Jackson 时最常见的配置之一，因为我们经常需要将外部 REST API 的 JSON 结果映射到API 实体的<strong>内部 Java 表示。</strong></p>`,29),o=[p];function c(l,i){return s(),a("div",null,o)}const r=n(e,[["render",c],["__file","jackson-unknown-properties.html.vue"]]);export{r as default};
